create table `employee_tracking_sessions` (`id` bigint unsigned not null auto_increment primary key, `uuid` varchar(36) not null, `organization_id` int unsigned not null, `employee_id` int unsigned not null, `session_date` date not null comment 'YYYY-MM-DD date of the session', `session_start` datetime null comment 'First location ping of the day', `session_end` datetime null comment 'Last location ping of the day', `total_working_minutes` int unsigned not null default '0' comment 'session_end - session_start - total_break_minutes', `total_break_minutes` int unsigned not null default '0' comment 'Sum of all stationary cluster durations >= 90s', `break_count` int unsigned not null default '0' comment 'Number of distinct break/stop events detected', `total_distance_km` decimal(10, 4) unsigned not null default '0' comment 'Sum of haversine distances between consecutive breadcrumbs', `ping_count` int unsigned not null default '0' comment 'Total number of location pings recorded for this session', `created_at` datetime not null, `updated_at` datetime not null);
alter table `employee_tracking_sessions` add unique `employee_tracking_sessions_uuid_unique`(`uuid`);
